/** The members of `Intent` that derive from the core's `SetupDraftIntent`. */
export type SetupDraftIntent =
    | AddSetupSpace
    | AdoptSetupDraft
    | CustomizeSetupSpace
    | MoveSetupSpace
    | RemoveSetupSpace;

/** The members of `Intent` that derive from the core's `SetupFlowIntent`. */
export type SetupFlowIntent =
    | AdoptSetupCompletion
    | BeginImportCommit
    | CancelImportRead
    | ChooseImportDestination
    | ContinueImport
    | CustomizeImportSpace
    | FailImport
    | FinishImportCommit
    | FinishSetup
    | IncludeImportExtension
    | IncludeImportPasswords
    | IncludeImportSpace
    | IncludeImportTabs
    | OfferImportSources
    | PlaceImportTab
    | ReviewImport
    | SeparateImportSpace
    | ShowImportSpace
    | ShowSetupStep
    | StartSetup
    | ToggleImportSource;

/** The members of `Intent` that derive from the core's `ShortcutIntent`. */
export type ShortcutIntent =
    | AdoptShiftedDigitShortcuts
    | AdoptShortcuts
    | AssignShortcut
    | ChooseShortcutPreference
    | ReassignShortcut
    | ResetShortcut
    | ResetShortcuts
    | UnassignShortcut;

/** The members of `Intent` that derive from the core's `SidebarDrop`. */
export type SidebarDrop =
    | DropAroundTab
    | DropIntoList
    | DropIntoSplit
    | DropOnSpace;

/** The members of `Intent` that derive from the core's `SitePermissionIntent`. */
export type SitePermissionIntent =
    | AdoptSitePermissions
    | DecideSitePermission
    | ResetSitePermission
    | ResetSpacePermissions;

/** The members of `Intent` that derive from the core's `SpaceAccessIntent`. */
export type SpaceAccessIntent =
    | BeginUnlockingSpace
    | FinishUnlockingSpace
    | LockAllSpaces
    | LockSpace;

/** The members of `Intent` that derive from the core's `WindowIntent`. */
export type WindowIntent =
    | AdoptOpenWindows
    | AdoptWindowRecords
    | BeginReopeningPages
    | CloseWindow
    | DismissShownTab
    | FinishReopeningPages
    | NoteLaunchRelease
    | OpenWindow
    | RememberWindowsForLaunch
    | ResizeSplitColumns
    | ShowAdjacentSpace
    | ShowAdjacentTab
    | ShowLeastRecentTab
    | ShowMostRecentTab
    | ShowSpace
    | ShowTab
    | TakeReleaseNotes;

/** The members of `Intent` that derive from the core's `WorkspaceIntent`. */
export type WorkspaceIntent =
    | BorrowSpace
    | CloseWorkspace
    | OpenWorkspace;

