export function readEngineQuestion(reader: WireReader): EngineQuestion {
    const tag = reader.readTag();
    switch (tag) {
        case 0: return readLinkActivation(reader);
        case 1: return readPageBlocksContent(reader);
        case 2: return readPageInjectedScript(reader);
        default: throw new Error(`Unknown EngineQuestion tag ${tag}.`);
    }
}

export function writeEngineQuestion(writer: WireWriter, value: EngineQuestion): void {
    switch (value.$kind) {
        case "LinkActivation": writer.writeTag(0); writeLinkActivation(writer, value); break;
        case "PageBlocksContent": writer.writeTag(1); writePageBlocksContent(writer, value); break;
        case "PageInjectedScript": writer.writeTag(2); writePageInjectedScript(writer, value); break;
        default: throw new Error(`Not a contract EngineQuestion: ${(value as { $kind: string }).$kind}.`);
    }
}

/** Reads what `question` answers with. */
export function readEngineQuestionAnswer<Q extends EngineQuestion>(question: Q, reader: WireReader): AnswerOfEngineQuestion<Q> {
    switch (question.$kind) {
        case "LinkActivation": return (readLinkNavigationAnswer(reader)) as unknown as AnswerOfEngineQuestion<Q>;
        case "PageBlocksContent": return (reader.readBool()) as unknown as AnswerOfEngineQuestion<Q>;
        case "PageInjectedScript": return (reader.readString()) as unknown as AnswerOfEngineQuestion<Q>;
        default: throw new Error(`Not a contract EngineQuestion: ${(question as { $kind: string }).$kind}.`);
    }
}

/** Writes what `question` answers with. */
export function writeEngineQuestionAnswer<Q extends EngineQuestion>(question: Q, writer: WireWriter, value: AnswerOfEngineQuestion<Q>): void {
    switch (question.$kind) {
        case "LinkActivation": {
            const answer = value as EngineQuestionAnswers["LinkActivation"];
            writeLinkNavigationAnswer(writer, answer);
            break;
        }
        case "PageBlocksContent": {
            const answer = value as EngineQuestionAnswers["PageBlocksContent"];
            writer.writeBool(answer);
            break;
        }
        case "PageInjectedScript": {
            const answer = value as EngineQuestionAnswers["PageInjectedScript"];
            writer.writeString(answer);
            break;
        }
        default: throw new Error(`Not a contract EngineQuestion: ${(question as { $kind: string }).$kind}.`);
    }
}

