export function readCredentialFormFacts(reader: WireReader): CredentialFormFacts {
    const event = readCredentialCaptureEvent(reader);
    const frameOrigin = readCredentialOrigin(reader);
    const topLevelOrigin = readCredentialOrigin(reader);
    const isMainFrame = reader.readBool();
    const hasFormId = reader.readBool();
    const fields = reader.readList(() => readFormField(reader));
    const focusedField = (reader.readPresence() ? reader.readInt32() : null);
    const submission = (reader.readPresence() ? readFormSubmission(reader) : null);
    const filledUsername = reader.readBool();
    const hasVisiblePasswordField = (reader.readPresence() ? reader.readBool() : null);
    const hasFillTarget = reader.readBool();
    const fieldRectInTopViewport = reader.readBool();
    return { event, frameOrigin, topLevelOrigin, isMainFrame, hasFormId, fields, focusedField, submission, filledUsername, hasVisiblePasswordField, hasFillTarget, fieldRectInTopViewport };
}
export function writeCredentialFormFacts(writer: WireWriter, value: CredentialFormFacts): void {
    writeCredentialCaptureEvent(writer, value.event);
    writeCredentialOrigin(writer, value.frameOrigin);
    writeCredentialOrigin(writer, value.topLevelOrigin);
    writer.writeBool(value.isMainFrame);
    writer.writeBool(value.hasFormId);
    writer.writeCount(value.fields.length);
    for (const fieldsItem of value.fields) {
        writeFormField(writer, fieldsItem);
    }
    if (value.focusedField !== null && value.focusedField !== undefined) {
        writer.writePresence(true);
        writer.writeInt32(value.focusedField);
    } else {
        writer.writePresence(false);
    }
    if (value.submission !== null && value.submission !== undefined) {
        writer.writePresence(true);
        writeFormSubmission(writer, value.submission);
    } else {
        writer.writePresence(false);
    }
    writer.writeBool(value.filledUsername);
    if (value.hasVisiblePasswordField !== null && value.hasVisiblePasswordField !== undefined) {
        writer.writePresence(true);
        writer.writeBool(value.hasVisiblePasswordField);
    } else {
        writer.writePresence(false);
    }
    writer.writeBool(value.hasFillTarget);
    writer.writeBool(value.fieldRectInTopViewport);
}

