export function readCredentialImportGroup(reader: WireReader): CredentialImportGroup {
    const origin = readCredentialOrigin(reader);
    const username = reader.readString();
    const candidates = reader.readList(() => readCredentialImportCandidate(reader));
    const collapsedDuplicateRowCount = reader.readInt32();
    const existingId = (reader.readPresence() ? reader.readGuid() : null);
    const suggestedRow = (reader.readPresence() ? reader.readInt32() : null);
    const requiresChoice = reader.readBool();
    return { origin, username, candidates, collapsedDuplicateRowCount, existingId, suggestedRow, requiresChoice };
}
export function writeCredentialImportGroup(writer: WireWriter, value: CredentialImportGroup): void {
    writeCredentialOrigin(writer, value.origin);
    writer.writeString(value.username);
    writer.writeCount(value.candidates.length);
    for (const candidatesItem of value.candidates) {
        writeCredentialImportCandidate(writer, candidatesItem);
    }
    writer.writeInt32(value.collapsedDuplicateRowCount);
    if (value.existingId !== null && value.existingId !== undefined) {
        writer.writePresence(true);
        writer.writeGuid(value.existingId);
    } else {
        writer.writePresence(false);
    }
    if (value.suggestedRow !== null && value.suggestedRow !== undefined) {
        writer.writePresence(true);
        writer.writeInt32(value.suggestedRow);
    } else {
        writer.writePresence(false);
    }
}

export function readCredentialImportPlan(reader: WireReader): CredentialImportPlan {
    const format = readCredentialFileFormat(reader);
    const groups = reader.readList(() => readCredentialImportGroup(reader));
    const rejections = reader.readList(() => readCredentialRowRejection(reader));
    const warnings = reader.readList(() => readCredentialRowWarning(reader));
    const validRowCount = reader.readInt32();
    const rejectionCounts = reader.readList(() => readCredentialRowFlawCount(reader));
    return { format, groups, rejections, warnings, validRowCount, rejectionCounts };
}
export function writeCredentialImportPlan(writer: WireWriter, value: CredentialImportPlan): void {
    writeCredentialFileFormat(writer, value.format);
    writer.writeCount(value.groups.length);
    for (const groupsItem of value.groups) {
        writeCredentialImportGroup(writer, groupsItem);
    }
    writer.writeCount(value.rejections.length);
    for (const rejectionsItem of value.rejections) {
        writeCredentialRowRejection(writer, rejectionsItem);
    }
    writer.writeCount(value.warnings.length);
    for (const warningsItem of value.warnings) {
        writeCredentialRowWarning(writer, warningsItem);
    }
}

