export function readDownloadState(reader: WireReader): DownloadState {
    const id = reader.readGuid();
    const profileId = reader.readGuid();
    const createdAt = reader.readDate();
    const filename = reader.readString();
    const destination = (reader.readPresence() ? reader.readString() : null);
    const progress = reader.readDouble();
    const telemetry = readDownloadTelemetry(reader);
    const phase = readDownloadPhase(reader);
    const failure = (reader.readPresence() ? readDownloadFailure(reader) : null);
    const message = (reader.readPresence() ? reader.readString() : null);
    const risk = (reader.readPresence() ? readDownloadRiskAssessment(reader) : null);
    const isAcknowledged = reader.readBool();
    const canPause = reader.readBool();
    const canResume = reader.readBool();
    return { id, profileId, createdAt, filename, destination, progress, telemetry, phase, failure, message, risk, isAcknowledged, canPause, canResume };
}
export function writeDownloadState(writer: WireWriter, value: DownloadState): void {
    writer.writeGuid(value.id);
    writer.writeGuid(value.profileId);
    writer.writeDate(value.createdAt);
    writer.writeString(value.filename);
    if (value.destination !== null && value.destination !== undefined) {
        writer.writePresence(true);
        writer.writeString(value.destination);
    } else {
        writer.writePresence(false);
    }
    writer.writeDouble(value.progress);
    writeDownloadTelemetry(writer, value.telemetry);
    writeDownloadPhase(writer, value.phase);
    if (value.failure !== null && value.failure !== undefined) {
        writer.writePresence(true);
        writeDownloadFailure(writer, value.failure);
    } else {
        writer.writePresence(false);
    }
    if (value.message !== null && value.message !== undefined) {
        writer.writePresence(true);
        writer.writeString(value.message);
    } else {
        writer.writePresence(false);
    }
    if (value.risk !== null && value.risk !== undefined) {
        writer.writePresence(true);
        writeDownloadRiskAssessment(writer, value.risk);
    } else {
        writer.writePresence(false);
    }
    writer.writeBool(value.isAcknowledged);
    writer.writeBool(value.canPause);
    writer.writeBool(value.canResume);
}

export function readDownloadTelemetry(reader: WireReader): DownloadTelemetry {
    const bytesReceived = reader.readInt64();
    const totalBytes = (reader.readPresence() ? reader.readInt64() : null);
    const bytesPerSecond = (reader.readPresence() ? reader.readDouble() : null);
    const estimatedTimeRemaining = (reader.readPresence() ? reader.readDouble() : null);
    const isPaused = reader.readBool();
    return { bytesReceived, totalBytes, bytesPerSecond, estimatedTimeRemaining, isPaused };
}
export function writeDownloadTelemetry(writer: WireWriter, value: DownloadTelemetry): void {
    writer.writeInt64(value.bytesReceived);
    if (value.totalBytes !== null && value.totalBytes !== undefined) {
        writer.writePresence(true);
        writer.writeInt64(value.totalBytes);
    } else {
        writer.writePresence(false);
    }
    if (value.bytesPerSecond !== null && value.bytesPerSecond !== undefined) {
        writer.writePresence(true);
        writer.writeDouble(value.bytesPerSecond);
    } else {
        writer.writePresence(false);
    }
    if (value.estimatedTimeRemaining !== null && value.estimatedTimeRemaining !== undefined) {
        writer.writePresence(true);
        writer.writeDouble(value.estimatedTimeRemaining);
    } else {
        writer.writePresence(false);
    }
    writer.writeBool(value.isPaused);
}

