export function readDropTargetList(reader: WireReader): DropTargetList {
    const refusal = (reader.readPresence() ? readRejection(reader) : null);
    const lists = reader.readList(() => readListDropTarget(reader));
    const spaceIds = reader.readList(() => reader.readGuid());
    const split = (reader.readPresence() ? readSplitDropTarget(reader) : null);
    const folderAroundTabIds = reader.readList(() => reader.readGuid());
    return { refusal, lists, spaceIds, split, folderAroundTabIds };
}
export function writeDropTargetList(writer: WireWriter, value: DropTargetList): void {
    if (value.refusal !== null && value.refusal !== undefined) {
        writer.writePresence(true);
        writeRejection(writer, value.refusal);
    } else {
        writer.writePresence(false);
    }
    writer.writeCount(value.lists.length);
    for (const listsItem of value.lists) {
        writeListDropTarget(writer, listsItem);
    }
    writer.writeCount(value.spaceIds.length);
    for (const spaceIdsItem of value.spaceIds) {
        writer.writeGuid(spaceIdsItem);
    }
    if (value.split !== null && value.split !== undefined) {
        writer.writePresence(true);
        writeSplitDropTarget(writer, value.split);
    } else {
        writer.writePresence(false);
    }
    writer.writeCount(value.folderAroundTabIds.length);
    for (const folderAroundTabIdsItem of value.folderAroundTabIds) {
        writer.writeGuid(folderAroundTabIdsItem);
    }
}

