export function readEngineDownload(reader: WireReader): EngineDownload {
    const downloadId = reader.readString();
    const profileId = reader.readGuid();
    const sourcePageId = (reader.readPresence() ? reader.readGuid() : null);
    const filename = reader.readString();
    const path = (reader.readPresence() ? reader.readString() : null);
    const received = reader.readInt64();
    const total = reader.readInt64();
    const startedAt = reader.readDate();
    const restored = reader.readBool();
    const paused = reader.readBool();
    const state = readEngineDownloadState(reader);
    const warning = (reader.readPresence() ? readEngineDownloadWarning(reader) : null);
    const interruption = (reader.readPresence() ? readEngineDownloadInterruption(reader) : null);
    const failureDetail = (reader.readPresence() ? reader.readString() : null);
    const approvalToken = reader.readString();
    const canPause = reader.readBool();
    const canResume = reader.readBool();
    return { downloadId, profileId, sourcePageId, filename, path, received, total, startedAt, restored, paused, state, warning, interruption, failureDetail, approvalToken, canPause, canResume };
}
