    const showingSpaceId = (reader.readPresence() ? reader.readGuid() : null);
    const showingTabs = reader.readList(() => readShownTab(reader));
    const restoresTabs = reader.readBool();
    return { $kind: "OpenWindow", windowId, workspaceId, saved, copyingWindowId, showingSpaceId, showingTabs, restoresTabs };
