export function readPageNetworkRequest(reader: WireReader): PageNetworkRequest {
    const sequence = reader.readInt64();
    const url = reader.readString();
    const method = reader.readString();
    const resourceType = reader.readString();
    const status = reader.readInt32();
    const mimeType = (reader.readPresence() ? reader.readString() : null);
    const requestHeaders = reader.readList(() => readPageHeader(reader));
    const responseHeaders = reader.readList(() => readPageHeader(reader));
    const started = reader.readDate();
    const duration = reader.readDouble();
    const bytes = reader.readInt64();
    const failure = (reader.readPresence() ? reader.readString() : null);
    return { sequence, url, method, resourceType, status, mimeType, requestHeaders, responseHeaders, started, duration, bytes, failure };
}
export function writePageNetworkRequest(writer: WireWriter, value: PageNetworkRequest): void {
    writer.writeInt64(value.sequence);
    writer.writeString(value.url);
    writer.writeString(value.method);
    writer.writeString(value.resourceType);
    writer.writeInt32(value.status);
    if (value.mimeType !== null && value.mimeType !== undefined) {
        writer.writePresence(true);
        writer.writeString(value.mimeType);
    } else {
        writer.writePresence(false);
    }
    writer.writeCount(value.requestHeaders.length);
    for (const requestHeadersItem of value.requestHeaders) {
        writePageHeader(writer, requestHeadersItem);
    }
    writer.writeCount(value.responseHeaders.length);
    for (const responseHeadersItem of value.responseHeaders) {
        writePageHeader(writer, responseHeadersItem);
    }
    writer.writeDate(value.started);
    writer.writeDouble(value.duration);
    writer.writeInt64(value.bytes);
    if (value.failure !== null && value.failure !== undefined) {
        writer.writePresence(true);
        writer.writeString(value.failure);
    } else {
        writer.writePresence(false);
    }
}

