export function readPresentPage(reader: WireReader): PresentPage {
    const surface = (reader.readPresence() ? readTabSurface(reader) : null);
    const hasPage = reader.readBool();
    const hasNavigationFailure = reader.readBool();
    const hasProcessFailure = reader.readBool();
    const restoresUnloaded = reader.readBool();
    return { $kind: "PresentPage", surface, hasPage, hasNavigationFailure, hasProcessFailure, restoresUnloaded };
}
export function writePresentPage(writer: WireWriter, value: PresentPage): void {
    if (value.surface !== null && value.surface !== undefined) {
        writer.writePresence(true);
        writeTabSurface(writer, value.surface);
    } else {
        writer.writePresence(false);
    }
    writer.writeBool(value.hasPage);
    writer.writeBool(value.hasNavigationFailure);
    writer.writeBool(value.hasProcessFailure);
    writer.writeBool(value.restoresUnloaded);
}

