export function readSetupFlowState(reader: WireReader): SetupFlowState {
    const workspaceId = reader.readGuid();
    const entry = readSetupEntry(reader);
    const step = readSetupStep(reader);
    const backStep = (reader.readPresence() ? readSetupStep(reader) : null);
    const nextStep = (reader.readPresence() ? readSetupStep(reader) : null);
    const phase = readSetupPhase(reader);
    const offered = reader.readList(() => readImportSource(reader));
    const selected = reader.readList(() => readImportSource(reader));
    const queue = (reader.readPresence() ? readSetupImportQueue(reader) : null);
    const source = (reader.readPresence() ? readImportSource(reader) : null);
    const review = (reader.readPresence() ? readSetupImportReview(reader) : null);
    const failure = (reader.readPresence() ? readSetupFailure(reader) : null);
    const summary = (reader.readPresence() ? readSetupSummary(reader) : null);
    const opensGuide = reader.readBool();
    const opensCrestFromWelcome = reader.readBool();
    const look = readSetupLook(reader);
    return { workspaceId, entry, step, backStep, nextStep, phase, offered, selected, queue, source, review, failure, summary, opensGuide, opensCrestFromWelcome, look };
}
export function writeSetupFlowState(writer: WireWriter, value: SetupFlowState): void {
    writer.writeGuid(value.workspaceId);
    writeSetupEntry(writer, value.entry);
    writeSetupStep(writer, value.step);
    if (value.backStep !== null && value.backStep !== undefined) {
        writer.writePresence(true);
        writeSetupStep(writer, value.backStep);
    } else {
        writer.writePresence(false);
    }
    if (value.nextStep !== null && value.nextStep !== undefined) {
        writer.writePresence(true);
        writeSetupStep(writer, value.nextStep);
    } else {
        writer.writePresence(false);
    }
    writeSetupPhase(writer, value.phase);
    writer.writeCount(value.offered.length);
    for (const offeredItem of value.offered) {
        writeImportSource(writer, offeredItem);
    }
    writer.writeCount(value.selected.length);
    for (const selectedItem of value.selected) {
        writeImportSource(writer, selectedItem);
    }
    if (value.queue !== null && value.queue !== undefined) {
        writer.writePresence(true);
        writeSetupImportQueue(writer, value.queue);
    } else {
        writer.writePresence(false);
    }
    if (value.source !== null && value.source !== undefined) {
        writer.writePresence(true);
        writeImportSource(writer, value.source);
    } else {
        writer.writePresence(false);
    }
    if (value.review !== null && value.review !== undefined) {
        writer.writePresence(true);
        writeSetupImportReview(writer, value.review);
    } else {
        writer.writePresence(false);
    }
    if (value.failure !== null && value.failure !== undefined) {
        writer.writePresence(true);
        writeSetupFailure(writer, value.failure);
    } else {
        writer.writePresence(false);
    }
    if (value.summary !== null && value.summary !== undefined) {
        writer.writePresence(true);
        writeSetupSummary(writer, value.summary);
    } else {
        writer.writePresence(false);
    }
    writer.writeBool(value.opensGuide);
    writer.writeBool(value.opensCrestFromWelcome);
    writeSetupLook(writer, value.look);
}

